msg.headers = {
    'Content-Type': 'application/x-www-form-urlencoded'
};
msg.payload = `grant_type=client_credentials&client_id=${msg.clientId}&client_secret=${msg.clientSecret}`;
return msg;

if (!msg.payload || !msg.payload.access_token) {
    node.error("取得 Token 失敗！");
    return null;
}
var token = msg.payload.access_token;
msg.headers = {
    'Authorization': 'Bearer ' + token,
    'Accept': 'application/json'
};
msg.url = 'https://tdx.transportdata.tw/api/basic/v2/Bus/EstimatedTimeOfArrival/City/Taipei/承德幹線?$format=JSON';
msg.payload = null;
return msg;

var data = msg.payload;
if (!Array.isArray(data)) {
    return msg;
}
var targetStopName = "圓山皇宮大廈";
var filtered = data.filter(function(item) {
    return item.StopName && item.StopName.Zh_tw && item.StopName.Zh_tw.indexOf(targetStopName) !== -1;
});
var result = filtered.map(function(item) {
    var direction = item.Direction === 0 ? "去程 (往新北投)" : "回程 (往捷運石牌)";
    var timeInMin = item.EstimateTime !== undefined ? Math.round(item.EstimateTime / 60) + " 分鐘" : "未發車/末班已過";
    return {
        路線: "承德幹線",
        站牌: targetStopName,
        方向: direction,
        到站時間: timeInMin
    };
});
msg.payload = result;
return msg;

